const input = $input.first().json;
const creds = input.credentials || {};
const googleToken = creds.google?.access_token || '';
const args = input.args || {};
const days = args.days || 1;
if (!googleToken) throw new Error('Google not connected — ask user to connect Google in setup');
// Calculate time range
const now = new Date();
const end = new Date(now.getTime() + days * 24 * 60 * 60 * 1000);
return [{ json: {
  access_token: googleToken,
  timeMin: now.toISOString(),
  timeMax: end.toISOString()
} }];

const events = $input.first().json.items || [];
const eventsText = events.map(ev => {
  const start = ev.start?.dateTime || ev.start?.date || 'unknown';
  const end = ev.end?.dateTime || ev.end?.date || '';
  const attendees = (ev.attendees || []).map(a => a.email).join(', ') || 'none';
  return `Event: ${ev.summary || '(no title)'}\n  Start: ${start}\n  End: ${end}\n  Attendees: ${attendees}\n  Location: ${ev.location || 'none'}\n`;
}).join('\n---\n');
return [{ json: { events_text: eventsText || 'No upcoming events.', count: events.length } }];

const summary = $input.first().json.message?.content || '';
const count = $('Build Events Summary').item.json.count;
return [{ json: { summary: summary, event_count: count } }];
